    async fn accept_transit_gateway_vpc_attachment(
        &self,
        input: AcceptTransitGatewayVpcAttachmentRequest,
    ) -> Result<
        AcceptTransitGatewayVpcAttachmentResult,
        RusotoError<AcceptTransitGatewayVpcAttachmentError>,
    >;

